import{_ as e,o,c as a,a2 as d}from"./chunks/framework.C2TvIV46.js";const p=JSON.parse('{"title":"ワークスペース","description":"","frontmatter":{},"headers":[],"relativePath":"ja/megacrow/workspaces.md","filePath":"ja/megacrow/workspaces.md"}'),r={name:"ja/megacrow/workspaces.md"};function l(s,t,n,i,c,g){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="ワークスペース" tabindex="-1">ワークスペース <a class="header-anchor" href="#ワークスペース" aria-label="Permalink to &quot;ワークスペース&quot;">​</a></h1><p><strong>ワークスペース</strong> は、MegaloEvolved を Halo Reach Editing Kit（HREK）の Megalo スクリプトフォルダに向け、Files サイドバーから <code>.txt</code> ゲームタイプの参照、開く、コンパイルを行えるようにします。</p><p>ワークスペースは <strong>デスクトップ（Tauri）</strong> アプリで利用できます。Files パネルのヘッダーから切り替えを開きます。</p><h2 id="ワークスペース一覧" tabindex="-1">ワークスペース一覧 <a class="header-anchor" href="#ワークスペース一覧" aria-label="Permalink to &quot;ワークスペース一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>内容</th></tr></thead><tbody><tr><td><strong>行を選択</strong></td><td>そのワークスペースをアクティブにし、Files ツリーにスクリプトフォルダを読み込みます</td></tr><tr><td><strong>Active</strong> バッジ</td><td>現在使用中のワークスペースを示します</td></tr><tr><td><strong>Edit</strong></td><td>名前、スクリプトフォルダ、出力フォルダを変更するワークスペースダイアログを開きます</td></tr><tr><td><strong>Delete</strong></td><td>MegaloEvolved からワークスペースを削除します（ディスク上のファイルは削除しません）</td></tr><tr><td><strong>Add workspace…</strong></td><td>新しいワークスペースを作成します</td></tr></tbody></table><p>各行には、そのワークスペースの Megalo バージョン（現在は <strong>107 MCC — Halo Reach</strong>）とスクリプトフォルダのパスも表示されます。</p><h2 id="追加-編集のフィールド" tabindex="-1">追加／編集のフィールド <a class="header-anchor" href="#追加-編集のフィールド" aria-label="Permalink to &quot;追加／編集のフィールド&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>はい</td><td>ワークスペース切り替えに表示される名前。スクリプトフォルダを選ぶと、名前が空の場合は HREK の <code>project.xml</code> から自動入力されることがあります。</td></tr><tr><td><strong>Megalo version</strong></td><td>固定</td><td>Reach MCC（<code>107</code>）。他のゲーム／バージョンはまだ選択できません。</td></tr><tr><td><strong>Scripts folder</strong></td><td>はい</td><td>Megalo ソースのルートフォルダ（通常は <code>…\\data\\multiplayer\\megalo</code>）。インクルード、相対パス、Files ツリーはこの場所を基準に解決されます。</td></tr><tr><td><strong>Output folder</strong></td><td>いいえ</td><td><strong>Build</strong> でコンパイルした <code>.mglo</code> の出力先。通常は <code>…\\maps\\megalo</code>。省略しても閲覧と編集はできますが、Build には出力パスが必要です。</td></tr></tbody></table><h3 id="パスの推測" tabindex="-1">パスの推測 <a class="header-anchor" href="#パスの推測" aria-label="Permalink to &quot;パスの推測&quot;">​</a></h3><p>スクリプトフォルダを参照すると、MegaloEvolved は次を試みます。</p><ol><li>ワークスペース名用に HREK の <code>project.xml</code> 表示名を読む</li><li>既に存在する兄弟フォルダ <code>maps\\megalo</code> を出力フォルダとして検出する</li></ol><p>どちらのフィールドもあとから上書きできます。</p><h2 id="ヒント" tabindex="-1">ヒント <a class="header-anchor" href="#ヒント" aria-label="Permalink to &quot;ヒント&quot;">​</a></h2><ul><li>スクリプトは単一ファイルではなく、HREK の Megalo データツリーを指定してください。</li><li>ゲーム内ホットリロード向けに <code>maps/megalo</code> へワンクリック Build したい場合は、出力フォルダを設定してください。</li><li>複数のワークスペース（例: 別々の MOD）を保持し、フォルダを選び直さずに切り替えられます。</li></ul>',14)])])}const m=e(r,[["render",l]]);export{p as __pageData,m as default};
